using UnityEngine;

namespace GliderJam.Race
{
	// The race line through the level (generated by the RouteBuilder editor tool):
	// a dense flyable path plus the indices of the checkpoint rings along it (the last one is the finish).
	public class RaceRoute : MonoBehaviour
	{
		public Vector3[] path = new Vector3[0];
		public int[] checkpoints = new int[0];
		public float checkpointRadius = 42f;
		public float finishRadius = 70f;
		public float ceiling = 288f;

		public int CheckpointCount => checkpoints.Length;

		public Vector3 CheckpointPosition(int i)
		{
			return path[checkpoints[i]];
		}

		public Vector3 CheckpointForward(int i)
		{
			int p = checkpoints[i];
			Vector3 a = path[Mathf.Max(0, p - 2)], b = path[Mathf.Min(path.Length - 1, p + 2)];
			return (b - a).normalized;
		}

		public float Radius(int i)
		{
			return i == checkpoints.Length - 1 ? finishRadius : checkpointRadius;
		}

		// Distance along the path from the start to the closest path point (coarse, for ranking).
		public float Progress(Vector3 pos, int fromIndex, int toIndex)
		{
			fromIndex = Mathf.Clamp(fromIndex, 0, path.Length - 1);
			toIndex = Mathf.Clamp(toIndex, fromIndex, path.Length - 1);
			int best = fromIndex;
			float bestD = float.MaxValue;
			for (int i = fromIndex; i <= toIndex; i++)
			{
				float d = (path[i] - pos).sqrMagnitude;
				if (d < bestD)
				{
					bestD = d;
					best = i;
				}
			}
			return best;
		}

		// Point on the path a given number of samples ahead of the closest point to pos (autopilot / respawn).
		public int ClosestIndex(Vector3 pos, int hint, int window = 60)
		{
			int from = Mathf.Max(0, hint - window), to = Mathf.Min(path.Length - 1, hint + window);
			int best = from;
			float bestD = float.MaxValue;
			for (int i = from; i <= to; i++)
			{
				float d = (path[i] - pos).sqrMagnitude;
				if (d < bestD)
				{
					bestD = d;
					best = i;
				}
			}
			return best;
		}

		private void OnDrawGizmos()
		{
			Gizmos.color = Color.yellow;
			for (int i = 1; i < path.Length; i++)
			{
				Gizmos.DrawLine(path[i - 1], path[i]);
			}
			Gizmos.color = Color.cyan;
			for (int i = 0; i < checkpoints.Length; i++)
			{
				Gizmos.DrawWireSphere(CheckpointPosition(i), Radius(i));
			}
		}
	}
}
